<script setup>

definePageMeta({
    nav: false,
    footer: false
})

const router = useRouter()

const ageVerificationError = ref({
    msg: "",
    bool: false
})


onMounted(()=>{
        // Basic form validation
        document.getElementById('age-verification-form').addEventListener('submit', function(e) {
            e.preventDefault();
            
            ageVerificationError.value.bool = false
            ageVerificationError.value.msg = ""

            const day = parseInt(document.getElementById('day').value, 10);
            const month = parseInt(document.getElementById('month').value, 10);
            const year = parseInt(document.getElementById('year').value, 10);
            
            // Basic validation
            if (isNaN(day) || day < 1 || day > 31) {
                ageVerificationError.value.bool = true
                ageVerificationError.value.msg = 'Please enter a valid day'
                return;
            }
            
            if (isNaN(month) || month < 1 || month > 12) {
                ageVerificationError.value.bool = true
                ageVerificationError.value.msg = 'Please enter a valid month'
                return;
            }
            
            if (isNaN(year) || year < 1900 || year > new Date().getFullYear()) {
                ageVerificationError.value.bool = true
                ageVerificationError.value.msg = 'Please enter a valid year'
                return;
            }
            
            // Calculate age
            const birthDate = new Date(year, month - 1, day);
            const today = new Date();
            let age = today.getFullYear() - birthDate.getFullYear();
            const monthDiff = today.getMonth() - birthDate.getMonth();
            
            if (monthDiff < 0 || (monthDiff === 0 && today.getDate() < birthDate.getDate())) {
                age--;
            }
            
            // Check if user is of legal age (21 for US, 18 for most other countries)
            // This is a simplified example - actual legal ages vary by country
            const legalAge = 21;
            
            if (age >= legalAge) {
                // save the verification on local storage of reuse which will be valid for 10 days
                window.localStorage.setItem('ageVerifiedDate',Date.now())
                router.push('/')

            } else {
                ageVerificationError.value.bool = true
                ageVerificationError.value.msg = 'Sorry, you must be of legal drinking age to enter this site.'
            }
        });

    // Auto-tab between inputs
    document.getElementById('day').addEventListener('input', function() {
        if (this.value.length === 2) {
            document.getElementById('month').focus();
        }
    });
    
    document.getElementById('month').addEventListener('input', function() {
        if (this.value.length === 2) {
            document.getElementById('year').focus();
        }
    });
})


</script>
